import{_ as p,a0 as o,w as r,s as b,ao as i,I as s,x as u,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"Ubuntu 13.10 之於 Ubuntu 13.04，給我一個升級的理由 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 13.10 之於 Ubuntu 13.04，給我一個升級的理由 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 13.10 之於 Ubuntu 13.04，給我一個升級的理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 13.10 之於 Ubuntu 13.04，給我一個升級的理由 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade","title":"Ubuntu 13.10 之於 Ubuntu 13.04，給我一個升級的理由","tag":"201310","desc":""},"relativePath":"201310/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade.md","filePath":"[post].md"}'),l={name:"201310/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade.md"};function U(d,t,m,T,f,g){const n=o("Link");return r(),b("div",null,[t[11]||(t[11]=i('<h1 id="ubuntu-13-10-之於-ubuntu-13-04-給我一個升級的理由" tabindex="-1">Ubuntu 13.10 之於 Ubuntu 13.04，給我一個升級的理由 <a class="header-anchor" href="#ubuntu-13-10-之於-ubuntu-13-04-給我一個升級的理由" aria-label="Permalink to “Ubuntu 13.10 之於 Ubuntu 13.04，給我一個升級的理由”">​</a></h1><p><strong>Ubuntu 13.10(Saucy Salamander)</strong> 將於10月17日發佈，但是這個由Canonical開發的操作系統的用户就有疑問了，新的版本似乎並沒有添加多少新的特性，有鑑於此，為什麼他們要更新呢？</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade-389846-2.jpg" alt="img"></p><p>Canonical的主要精力花費在提升品質和改進已有的功能上，而不是巨大的變化。這就意味這最近的兩個版本不會有很大的不同，至少在表面上看起來是這樣的。</p><p>Ubuntu 13.04(Raring Ringtail)，相較而言，令人乏味，但是人們並沒有意識到Ubuntu每一次發佈的背後都意味着需要完成大量的工作，即使初看起來沒有太大的變動。</p><p>那麼，對於普通用户來説如果新的版本並沒有顯著的變更，為什麼還要升級到 Ubuntu 13.10呢？事實上,初看起來似乎幾乎沒什麼變化，然而許多東西已經升級改善，總會變得更好的(多數情況下是這樣)。</p><p>當然，最重要的一點，這次的發佈所帶的新的linux內核3.11.x，是目前為止最新的穩定版本。新內核版本支持更多的設備和硬件組件，更好的電源管理性能，還有很多很多其他方面的改善。</p><p>另外，GNOME也升級了。Canonical支持Unity桌面環境，但是仍然使用許多GNOME的軟件包。Ubuntu 13.10 (Saucy Salamander) 自帶有來自3.8 分支的應用，這些應用都非常棒，對偏好Ubuntu GNOME的用户來説尤其如此。</p><p>相對於之前的Lens功能，Smart Scopes仍然有大的改善：更好的集成並且提供更多的定向解答。</p><p>安全性設置全面更新了，現在用户可以對系統產生的流量有更多的控制。用户可以停止自己的PC或者laptop和Canonical服務器之間的通信。</p><p>Ubuntu 13.10 也為新的軟件包格式奠定了基礎。迄今，所有Ubuntu應用都是以deb格式提供的。不過用户需要事先安裝相關依賴項，或者用户選擇自己單獨安裝。</p><p>而使用新的Click包類型，所有的依賴項都可以在包本身內部獲得，這就意味着, 只要應用開發者使用的是ubuntu SDK, 用户就不會再碰到任何與當前使用版本不兼容的軟件包。</p><p>最後，Unity進行了大量改進，理應比任何以前的ubuntu版本工作得更出色。</p><p>如果這些緣由仍然不足以説服你升級ubuntu，那就只有等待Ubuntu 14.04 LTS的發行了。不過不保證新的版本會看起來跟Ubuntu 13.10有多麼大的不同。</p><hr>',15)),s("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://news.softpedia.com/news/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade-389846.shtml"},{default:a(()=>[...t[0]||(t[0]=[u("http://news.softpedia.com/news/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade-389846.shtml",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[2]||(t[2]=[u("LCTT",-1)])]),_:1}),t[5]||(t[5]=u(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:a(()=>[...t[3]||(t[3]=[u("Linux中國",-1)])]),_:1}),t[6]||(t[6]=u(" 榮譽推出",-1))]),s("p",null,[t[9]||(t[9]=u("譯者：",-1)),e(n,{href:"https://github.com/l3b2w1"},{default:a(()=>[...t[7]||(t[7]=[u("l3b2w1",-1)])]),_:1}),t[10]||(t[10]=u(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[u("wxy",-1)])]),_:1})])])}const w=p(l,[["render",U]]);export{S as __pageData,w as default};
